-- Read-only post-install checks. Each violations count must be zero.
select 'activity_rls' as check_name,count(*)as violations from pg_class where oid='public.task_activity_log'::regclass and not relrowsecurity;
select 'activity_table_privileges' as check_name,count(*)as violations from information_schema.role_table_grants where table_schema='public'and table_name='task_activity_log'and grantee in('PUBLIC','anon','authenticated','service_role');
select 'activity_column_privileges' as check_name,count(*)as violations from information_schema.role_column_grants where table_schema='public'and table_name='task_activity_log'and grantee in('PUBLIC','anon','authenticated','service_role');
select 'activity_helper_privileges' as check_name,count(*)as violations from pg_proc p cross join unnest(array['anon','authenticated','service_role'])r where p.oid in('public.task_app_activity_event()'::regprocedure,'public.task_app_record_activity(uuid,text,uuid,text,text,uuid[],jsonb)'::regprocedure)and has_function_privilege(r,p.oid,'execute');
select 'activity_read_privileges' as check_name,count(*)as violations from pg_proc p where p.oid='public.task_app_activity(uuid,text,text,text,timestamptz,timestamptz,uuid)'::regprocedure and(not has_function_privilege('authenticated',p.oid,'execute')or has_function_privilege('anon',p.oid,'execute')or has_function_privilege('service_role',p.oid,'execute'));
select 'activity_function_safety' as check_name,count(*)as violations from pg_proc where pronamespace='public'::regnamespace and proname in('task_app_activity','task_app_record_activity','task_app_activity_event')and(not prosecdef or proconfig is distinct from array['search_path=""']);
select 'activity_trigger_coverage' as check_name,9-count(*)as violations from pg_trigger where tgname='zz_activity_log'and not tgisinternal and tgenabled='O';
select 'activity_workspace_ownership' as check_name,count(*)as violations from public.task_activity_log a where not exists(select 1 from public.task_workspaces w where w.owner_id=a.owner_id);
